CREATE PROCEDURE [CDN].[POS_EksportKontakty] @RowVersion BIGINT, @PointOfSaleId INT AS BEGIN SET NOCOUNT ON;
declare @Typ_Osoba int = 8211 select 0 as [@RowVersion], ( select * from( select case when s.typ = 1 then Kns_GUID else Kns_GUID2 end as [@GUID], Kns_GUID as [@AddressGUID], s.typ as [@Type], case when s.typ = 2 then Kns_Email else Kns_telefon end as [@Value], DATEADD(second,Kns_CzasModyfikacji,convert(datetime,'01-01-1990',105)) as [@ModificationDate], case when KnS_Archiwalny = 0 then 'false' else 'true' end as [@IsObsolete] FROM CDN.POS_KntDoEksportu(@PointOfSaleId,0) JOIN CDN.KntOsoby ON KnS_KntNumer = KntGIDNumer cross apply(select 1 as typ union select 2) as s where Kns_Email <> '' and s.typ = 2 OR KnS_Telefon <> '' and s.typ = 1
union all
select distinct case when s.typ = 1 then Kna_GUID else Kna_GUIDdane end as [@GUID], kna_guid as [@AddressGUID], s.typ as [@Type], case when s.typ = 2 then Kna_Email else Kna_telefon1 end as [@Value], DATEADD(second,KnA_LastModL,convert(datetime,'01-01-1990',105)) as [@ModificationDate], case when KnA_DataArc = 0 then 'false' else 'true' end as [@IsObsolete] FROM CDN.POS_KntDoEksportu(@PointOfSaleId,0) join cdn.KntAdresy on KnA_KntNumer = KntGIDNumer join cdn.KrajeCelne on KnA_Kraj = KPC_Kod cross apply(select 1 as typ union select 2) as s where Kna_Email <> '' and s.typ = 2 OR KnA_Telefon1 <> '' and s.typ = 1
) a for xml path('Contact'), type) for xml path('Contacts') SET NOCOUNT OFF;
/*
union all
select distinct PcL_ObiektGUID as [@GUID], null as [@AddressGUID], null as [@Type], null as [@Value], null as [@ModificationDate], 'true' as [@IsObsolete] FROM cdn.PicoLog join cdn.PicoKonfig on PcL_PcKID = PcK_PicoID join cdn.PicoStanowiska on PcK_PicoID = PSa_PcKID where psa_id = @PointOfSaleId AND PcL_Komentarz = 'POS_ObsoleteObject' AND (PcL_TStamp < @RowVersion or @RowVersion = 0)
delete a FROM cdn.PicoLog a join cdn.PicoKonfig on PcL_PcKID = PcK_PicoID join cdn.PicoStanowiska on PcK_PicoID = PSa_PcKID where psa_id = @PointOfSaleId AND PcL_Komentarz = 'POS_ObsoleteObject' AND (PcL_TStamp < @RowVersion or @RowVersion = 0)
*/ END

CREATE PROCEDURE [CDN].[POS_EksportUsunieteObiekty] @RowVersion BIGINT, @PointOfSaleId INT AS BEGIN SET NOCOUNT ON; select DATEDIFF(second, convert(datetime,'01-01-1990',105),DateAdd(d,DateDiff(d, convert(datetime,'28-12-1800',105),getdate() ) ,convert(datetime,'28-12-1800',105))) as [@RowVersion], ( select PcL_Info as [@Type], PcL_ObiektGUID as [@Ident] FROM cdn.PicoLog join cdn.PicoKonfig on PcL_PcKID = PcK_PicoID join cdn.PicoStanowiska on PcK_PicoID = PSa_PcKID where psa_id = @PointOfSaleId AND PcL_Komentarz = 'POS_DeletedObject' AND (PcL_TStamp < @RowVersion or @RowVersion = 0) for xml path('DeletedObject'), type) for xml path('DeletedObjects')
delete a FROM cdn.PicoLog a join cdn.PicoKonfig on PcL_PcKID = PcK_PicoID join cdn.PicoStanowiska on PcK_PicoID = PSa_PcKID where psa_id = @PointOfSaleId AND PcL_Komentarz = 'POS_DeletedObject' AND (PcL_TStamp < @RowVersion or @RowVersion = 0) SET NOCOUNT OFF;
END

